<?php
namespace App\Domain\Fiscal;
use App\Domain\Tenancy\CurrentOrganization;use App\Models\{FiscalDocument,FiscalDocumentClassification,User};use Carbon\CarbonImmutable;use DomainException;use Illuminate\Support\Facades\DB;
final class FiscalVoucherClassificationManager {public function __construct(private readonly CurrentOrganization $currentOrganization){}public function classify(FiscalVoucherClassificationData $data,User $actor):FiscalDocumentClassification{$org=$this->organization($actor);if(blank($data->voucherClass)){throw new DomainException('La clase fiscal del comprobante es obligatoria.');}return DB::transaction(function()use($data,$actor,$org){$doc=FiscalDocument::query()->forOrganization($org)->lockForUpdate()->find($data->fiscalDocumentId);if(!$doc){throw new DomainException('El documento no pertenece a la organización activa.');}$existing=FiscalDocumentClassification::query()->where('fiscal_document_id',$doc->id)->first();if($existing){if($existing->voucher_class!==$data->voucherClass||$existing->voucher_code!==$data->voucherCode){throw new DomainException('El documento ya posee otra clasificación fiscal.');}return $existing;}return FiscalDocumentClassification::query()->create(['organization_id'=>$org,'fiscal_document_id'=>$doc->id,'voucher_class'=>$data->voucherClass,'voucher_code'=>$data->voucherCode,'classified_at'=>CarbonImmutable::now(),'classified_by_user_id'=>$actor->id]);},3);}private function organization(User $actor):int{$id=$this->currentOrganization->id($actor);if(!($this->currentOrganization->roleFor($actor)?->canManageOrganization()??false)){throw new DomainException('Sólo un administrador puede clasificar fiscalmente un documento.');}return $id;}}
